<?php require 'config/database.php';$q=trim($_GET['q']??'');$type=$_GET['type']??'';$sql="SELECT items.*, users.name AS owner_name FROM items JOIN users ON users.id=items.user_id WHERE 1";$params=[];$types='';if($q!==''){$sql.=" AND (items.title LIKE ? OR items.category LIKE ? OR items.location LIKE ?)";$s="%$q%";$params=[$s,$s,$s];$types='sss';}if(in_array($type,['lost','found'],true)){$sql.=" AND items.item_type=?";$params[]=$type;$types.='s';}$sql.=" ORDER BY items.created_at DESC";$stmt=$conn->prepare($sql);if($params){$stmt->bind_param($types,...$params);}$stmt->execute();$res=$stmt->get_result();$pageTitle='Browse Items';include 'header.php';?><h2>Browse Items</h2><form method="get"><label>Search</label><input type="text" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Title, category or location"><label>Type</label><select name="type"><option value="">All</option><option value="lost" <?=$type==='lost'?'selected':''?>>Lost</option><option value="found" <?=$type==='found'?'selected':''?>>Found</option></select><button class="btn" type="submit">Search</button></form><div class="grid"><?php while($row=$res->fetch_assoc()):?><div class="card"><h3><?=htmlspecialchars($row['title'])?></h3><p><strong>Type:</strong> <?=htmlspecialchars($row['item_type'])?></p><p><strong>Category:</strong> <?=htmlspecialchars($row['category'])?></p><p><strong>Location:</strong> <?=htmlspecialchars($row['location'])?></p><a class="btn" href="item-details.php?id=<?=(int)$row['id']?>">Details</a></div><?php endwhile;?></div><?php include 'footer.php'; ?>